def binary_search() -> None:
    """COBOL logic"""
    logger.info("Performing binary search")
    ws_low = 1
    ws_high = ws_table_size
    ws_found_flag = 'N'
    while ws_low > ws_high:
        ws_mid = (ws_low + ws_high) / 2
        if tbl_key[int(ws_mid)] == ws_search_key:
            ws_found_flag = 'Y'
            ws_found_index = int(ws_mid)
            break
        elif tbl_key[int(ws_mid)] < ws_search_key:
            ws_low = int(ws_mid) + 1
        else:
            ws_high = int(ws_mid) - 1

ws_hash_value = 0
ws_hash_table_size = 0
hash_key = []
hash_value = []
ws_lookup_result = 0

def hash_lookup() -> None:
    """COBOL logic"""
    logger.info("Performing hash lookup")
    ws_hash_value = 0
    if hash_key[ws_hash_value] == ws_search_key:
        ws_found_flag = 'Y'
        ws_lookup_result = hash_value[ws_hash_value]
    else:
        probe_hash_table()

ws_probe_start = 0

def probe_hash_table() -> None:
    """Probe hash table."""
    logger.info("Probing hash table")
    ws_probe_start = ws_hash_value
    ws_hash_value += 1
    while ws_hash_value == ws_probe_start:
        if ws_hash_value > ws_hash_table_size:
            ws_hash_value = 1
        if hash_key[ws_hash_value] == ws_search_key:
            ws_found_flag = 'Y'
            ws_lookup_result = hash_value[ws_hash_value]
            break
        if hash_key[ws_hash_value] == "":
            break
        ws_hash_value += 1

