def display_summary() -> None:
    """Display summary of processing."""
    logger.info("Displaying summary")
    ws_trans_count = 10
    ws_deposit_count = 5
    ws_withdrawal_count = 3
    ws_transfer_count = 2
    ws_error_count = 0
    ws_total_deposits = Decimal("1000.00")
    ws_total_withdrawals = Decimal("500.00")
