logger = logging.getLogger(__name__)

def evaluate_date(ws_last_run_date: int, interval: str) -> None:
    """Calculates the next run date based on the interval."""
    logger.info("Calculating next run date")
    if interval == 'DAILY': ws_next_run_date = integer_of_date(ws_last_run_date) + 1
    elif interval == 'WEEKLY': ws_next_run_date = integer_of_date(ws_last_run_date) + 7
    elif interval == 'MONTHLY': ws_next_run_date = integer_of_date(ws_last_run_date) + 30
    elif interval == 'QUARTERLY': ws_next_run_date = integer_of_date(ws_last_run_date) + 90
    elif interval == 'YEARLY': ws_next_run_date = integer_of_date(ws_last_run_date) + 365

def integer_of_date(date: int) -> int:
    """Convert date to integer."""
    logger.info("Converting date to integer")
    pass

