def dormant_account_check() -> None:
    """Dormant account check."""
    logger.info("Checking for dormant accounts")
    global ws_eof_flag
    ws_eof_flag = 'N'
    while ws_eof_flag != 'Y':
        try:
            ws_account_rec = read_account_file()
            check_activity()
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

